using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using CampaignDemo;
[InitializeOnLoad]
public static class PVEProfilesRuntimeVerification {
 static int stage;static double start;static readonly List<string> checks=new List<string>();
 static PVEProfilesRuntimeVerification(){if(SessionState.GetBool("PVEProfilesTest",false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/Battle01.unity");SessionState.SetBool("PVEProfilesTest",true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add("PASS "+label);}
 static void Poll(){try{
  if(EditorApplication.timeSinceStartup-start>120)throw new Exception("PVE test timeout");if(!EditorApplication.isPlaying||Time.time<1)return;var world=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(world==null||!world.Initialized)return;var ai=world.GetComponent<BattleAIController>();ai.enabled=false;var hud=UnityEngine.Object.FindObjectOfType<CampaignHUD>();
  if(stage==0){world.setup.modes.EnterInspectionMode();foreach(var unit in world.units)if(unit.ownerId=="A"){hud.SelectUnit(unit);break;}stage=1;return;}
  Check(world.units.Length==8,"old army deployment replaced with eight soldiers");var blues=new List<BattleUnit>();var reds=new List<BattleUnit>();foreach(var u in world.units){Check(u.combatDefinition.role==UnitRole.Infantry,"only infantry deployed");Check(u.OnMap,"infantry initialized");Check(u.GetComponent<ArmyFreeMarchMover>().CanTraverse(world.setup.freeMarchMap,new RoadPoint(u.transform.position.x,u.transform.position.y),new RoadPoint(u.transform.position.x,u.transform.position.y)),"legal ground spawn");(u.ownerId=="A"?blues:reds).Add(u);}
  Check(blues.Count==4&&reds.Count==4,"four armies each faction");for(int i=0;i<blues.Count;i++)for(int j=i+1;j<blues.Count;j++)Check(Vector2.Distance(blues[i].transform.position,blues[j].transform.position)>3,"blue armies not crowded");for(int i=0;i<reds.Count;i++)for(int j=i+1;j<reds.Count;j++)Check(Vector2.Distance(reds[i].transform.position,reds[j].transform.position)>3,"red armies not crowded");
  var catalog=AssetDatabase.LoadAssetAtPath<UnitSymbolCatalog>("Assets/Resources/UnitSymbols.asset");Check(catalog.enemyUnknown!=null,"new unknown enemy artwork linked");float footWidth=BoldSymbolsAndPVEInstaller.VisibleWidth(catalog.friendly[0]);foreach(var city in world.points)if(city.kind==FacilityKind.RecoveryPoint){Check(city.GetComponent<SpriteRenderer>().sortingOrder>blues[0].GetComponent<SpriteRenderer>().sortingOrder,"city layer above armies");Check(BoldSymbolsAndPVEInstaller.VisibleWidth(city.GetComponent<SpriteRenderer>().sprite)*city.transform.localScale.x>=footWidth*1.35f,"city visibly larger than infantry");}
  Check(ai.profile!=null&&!ai.profile.patrol&&!ai.profile.artillery&&!ai.profile.reinforcement&&!ai.profile.recovery&&!ai.profile.supply&&!ai.profile.enemyMemory,"baseline profile has no optional skills");foreach(var red in reds)Check(red.GetComponent<AIUnitOrder>()!=null,"AI automatically deployed on B army");ai.Tick(.25f);Check(ai.Orders.Count==4,"AI controls only B armies");
  world.setup.modes.EnterInspectionMode();hud.SelectUnit(blues[0]);Capture(world,hud,"bold-pve-observation-preview.png");
  Check(hud.PlayerSwitchButton!=null,"player switching button available in mode 3");hud.PlayerSwitchButton.onClick.Invoke();Check(!ai.aiEnabled,"switch to B turns AI off immediately");int before=reds[0].GetComponent<AIUnitOrder>().SubmittedCommands;ai.Tick(10);Check(reds[0].GetComponent<AIUnitOrder>().SubmittedCommands==before,"manual B receives no AI commands");hud.PlayerSwitchButton.onClick.Invoke();Check(ai.aiEnabled,"switch back to A enables AI immediately");
  var order=reds[0].GetComponent<AIUnitOrder>();var recovery=reds[0].gameObject.AddComponent<AIRecoveryResponse>();recovery.keepLastCityGuard=false;reds[0].Damage(reds[0].Personnel*.7f);ai.Tick(.25f);Check(reds[0].Point==null&&order.State!=AIUnitState.Responding,"disabled recovery cannot activate on low strength");recovery.enabled=false;
  var originalBlue=blues[0].transform.position;blues[0].transform.position=reds[0].transform.position+Vector3.right*.2f;ai.profile.reactionSeconds=2;order.ResumeTask();ai.Tick(.5f);Check(order.State==AIUnitState.Reacting,"reaction time taken from editable profile");ai.Tick(1.6f);Check(order.State==AIUnitState.Engaging,"configured reaction delay eventually engages");blues[0].transform.position=originalBlue;
  var task=ScriptableObject.CreateInstance<AITaskDefinition>();task.kind=AITaskKind.Reinforce;task.useRoad=false;task.arrivalAction=AIArrivalAction.Hold;task.waypoints=new[]{(Vector2)reds[0].transform.position};ai.AssignTask(order,task);ai.Tick(.25f);Check(order.life==AITaskLife.Cancelled&&order.finishReason=="能力未开启","optional reinforcement blocked by basic profile");var optional=ScriptableObject.CreateInstance<AIBehaviorProfile>();optional.reinforcement=true;order.profileOverride=optional;order.ResetTask(task);ai.Tick(.25f);Check(order.life==AITaskLife.Completed&&!reds[0].Motor.IsMoving,"arrival hold completes and stops route");Check(!ai.reservations.HasTask(order.RuntimeTaskId),"arrival releases unit reservation");
  var ledger=ai.reservations;order.ResetTask(ai.defaultGuard);order.requiredUnits=new[]{reds[1]};ai.Tick(.25f);string token=order.RuntimeTaskId;Check(ledger.Reserve(token,"test-city",10,100),"resource reservation accepted");ledger.SetIncoming(token,"test-city",5);reds[1].Eliminate();ai.Tick(.25f);Check(order.life==AITaskLife.Cancelled&&order.finishReason.Contains("缺员"),"missing required unit cancels parent task");Check(!ledger.HasTask(token)&&ledger.ReservedAt("test-city")==0&&ledger.IncomingAt("test-city")==0,"missing member releases resources and incoming promises");
  order.requiredUnits=new BattleUnit[0];order.ResetTask(ai.defaultGuard);ai.Tick(.25f);token=order.RuntimeTaskId;Check(ledger.Reserve(token,"test-city",20,100),"explicit cancellation test reserves stock");ai.CancelTask(order,"测试取消");Check(!ledger.HasTask(token)&&order.life==AITaskLife.Cancelled,"explicit cancellation releases all claims");var deadOrder=reds[2].GetComponent<AIUnitOrder>();ai.Tick(.25f);token=deadOrder.RuntimeTaskId;ledger.Reserve(token,"test-city",5,100);reds[2].Eliminate();ai.Tick(.25f);Check(deadOrder.life==AITaskLife.Cancelled&&!ledger.HasTask(token),"unit death terminates task and reservations");
  foreach(var blue in blues)blue.transform.position=new Vector3(1000,1000);var observer=reds[3];blues[0].transform.position=observer.transform.position+Vector3.right*.2f;ai.profile.enemyMemory=false;ai.intel.Observe(10);Check(Find(ai.intel,blues[0].unitId)!=null,"current visible enemy enters filtered intelligence");blues[0].transform.position=new Vector3(1000,1000);ai.intel.Observe(11);Check(Find(ai.intel,blues[0].unitId)==null,"basic profile forgets disappeared contact");ai.profile.enemyMemory=true;ai.profile.enemyMemorySeconds=6;blues[0].transform.position=observer.transform.position+Vector3.right*.2f;var seen=blues[0].transform.position;ai.intel.Observe(20);blues[0].transform.position=new Vector3(1000,1000);ai.intel.Observe(25);var remembered=Find(ai.intel,blues[0].unitId);Check(remembered!=null&&!remembered.visible&&remembered.lastObservedPosition==seen,"memory freezes last observation instead of following hidden movement");ai.intel.Observe(27);Check(Find(ai.intel,blues[0].unitId)==null,"editable memory duration expires record");
  Check(ai.intel.OwnUnits().Length==2,"intelligence reports only surviving owned troops");foreach(var info in ai.intel.OwnCities())Check(info.own,"city interface does not expose enemy internal stock");
  File.WriteAllText("pve-profiles-runtime-verification.txt",checks.Count+" checks passed\n"+string.Join("\n",checks));Debug.Log("PVE_PROFILES_VERIFIED "+checks.Count);SessionState.SetBool("PVEProfilesTest",false);EditorApplication.update-=Poll;EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);File.WriteAllText("pve-profiles-runtime-verification.txt",e+"\n"+string.Join("\n",checks));SessionState.SetBool("PVEProfilesTest",false);EditorApplication.update-=Poll;EditorApplication.Exit(1);}}
 static AIContactRecord Find(AIFactionIntel intel,string id){foreach(var record in intel.Contacts)if(record.id==id)return record;return null;}
 static void Capture(BattleWorld world,CampaignHUD hud,string path){var canvas=hud.GetComponentInParent<Canvas>();var camera=world.setup.mapCamera;var texture=new RenderTexture(1600,900,24);var oldTarget=camera.targetTexture;var oldMode=canvas.renderMode;var oldCamera=canvas.worldCamera;int oldSort=canvas.sortingOrder;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.sortingOrder=1000;canvas.planeDistance=1;camera.targetTexture=texture;hud.GetComponent<TacticalMinimap>().Render();Canvas.ForceUpdateCanvases();camera.Render();var active=RenderTexture.active;RenderTexture.active=texture;var image=new Texture2D(1600,900,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,900),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());RenderTexture.active=active;camera.targetTexture=oldTarget;canvas.renderMode=oldMode;canvas.worldCamera=oldCamera;canvas.sortingOrder=oldSort;UnityEngine.Object.DestroyImmediate(image);texture.Release();UnityEngine.Object.DestroyImmediate(texture);}
}

